import {chapterTreasure} from './repertoire.js?v=5.38';
import {investigationProps,investigationProfile,interactInvestigation} from './exploration-investigations.js?v=5.16.0';
export {investigationView,validateExploration} from './exploration-investigations.js?v=5.16.0';
/** Optional, persistent exploration. No native story flags or mandatory tasks are reused. */
import {findPath} from './navigation.js?v=5.5.0';
export function explorationState(w){return w.state.exploration??={version:1,found:[],solved:[],relics:[],seen:[]};}
export function explorationVisible(w,o){if(!o.exploreId)return true;const e=explorationState(w);if(o.type==='secret'&&e.found.includes(o.exploreId))return false;if(o.hidden){const d=Math.hypot(w.state.x-o.xy[0]-.5,w.state.y-o.xy[1]-.5);return d<2.7;}return true;}
export function explorationDone(w,o){const e=explorationState(w);return o.type==='secret'?e.found.includes(o.exploreId):o.type==='riddle'?e.solved.includes(o.exploreId):false;}
export function explorationInteraction(w,o){if(!o.exploreId)return false;const e=explorationState(w),chapter=w.scene.chapter;
 if(interactInvestigation(w,o,e))return true;
 if(o.type==='clue'){if(!e.seen.includes(o.exploreId))e.seen.push(o.exploreId);w.text(o.text);return true;}
 if(o.type==='riddle'){if(e.solved.includes(o.exploreId)){w.text('The hidden compartment is open. '+o.memory);return true;}w.choose(o.prompt,o.options.map((label,i)=>[label,()=>{if(i!==o.answer)return w.text(o.failure);e.solved.push(o.exploreId);w.text(o.success);w.callbacks.onMusic('instrument:discovery');}]));return true;}
 if(o.type==='secret'){if(e.found.includes(o.exploreId))return true;if(o.lock&&!e.solved.includes(o.lock)){w.text(o.locked);return true;}e.found.push(o.exploreId);const special=chapterTreasure(chapter);w.state.items[special.id]=(w.state.items[special.id]||0)+1;const reward=o.reward||{};for(const k of ['tonic','ether','revive'])w.state.items[k]+=reward[k]||0;w.state.gold+=reward.gold||0;if(o.relic){e.relics.push({chapter,name:o.relic,text:o.memory});}const entries=Object.entries(reward).filter(([,v])=>v).map(([k,v])=>`${v} ${k==='gold'?'credits':k==='tonic'?'Tonics':k==='ether'?'Ethers':'Revives'}`);w.text([o.text,'Supplies: '+special.name+' · '+special.description,entries.length?'Found: '+entries.join(' · '):'',o.relic?'Keepsake: '+o.relic+'\n'+o.memory:'',`${e.found.length} hidden caches found · ${e.relics.length} keepsakes recovered`].filter(Boolean));w.callbacks.onMusic('instrument:treasure');return true;}
 return false;}
function reachable(r){const start=r.arrive,q=[start],seen=new Set([start.join(',')]);for(let i=0;i<q.length;i++){const[x,y]=q[i];for(const[a,b]of[[x+1,y],[x-1,y],[x,y+1],[x,y-1]])if(r.floor[b]?.[a]==='.'&&!seen.has(a+','+b)){seen.add(a+','+b);q.push([a,b]);}}return q;}
function place(r,from,used){const candidates=reachable(r).filter(([x,y])=>x>1&&y>1&&x<r.width-2&&y<r.height-2&&![...r.objects,...r.doors,...used].some(o=>{const p=o.xy||o.enemies?.[0]?.[1];return p&&Math.hypot(x-p[0],y-p[1])<1.35;}));candidates.sort((a,b)=>{const score=p=>Math.hypot(p[0]-from[0],p[1]-from[1])+(r.floor[p[1]-1]?.[p[0]]==='#'?3:0);return score(b)-score(a);});return candidates[0]||null;}
export function interiorFloor(kind,n){
 const width=22,height=19,g=Array.from({length:height},()=>Array(width).fill('#')),blocks=[];
 // All plans retain the authored clue alcoves and south vestibule.
 const spans={quarters:[[2,20],[2,20],[2,20],[2,20],[2,20],[2,20],[2,20],[2,20],[2,20],[2,20],[2,20],[2,20],[2,20],[7,15],[8,14],[9,12]],loft:[[2,20],[2,20],[2,20],[2,20],[2,20],[2,17],[2,17],[2,17],[2,17],[2,17],[2,17],[2,17],[2,17],[7,15],[8,14],[9,12]],archive:[[2,20],[2,20],[2,20],[2,20],[2,20],[2,20],[4,18],[4,18],[4,18],[4,18],[2,20],[2,20],[2,20],[6,16],[8,14],[9,12]],chapel:[[2,20],[2,20],[2,20],[7,15],[7,15],[3,19],[3,19],[3,19],[3,19],[7,15],[7,15],[7,15],[2,20],[7,15],[8,14],[9,12]],cistern:[[2,20],[2,20],[2,20],[3,19],[3,19],[3,19],[3,19],[3,19],[3,19],[3,19],[3,19],[3,19],[2,20],[7,15],[8,14],[9,12]],garden:[[2,20],[2,20],[2,20],[2,20],[2,20],[2,20],[4,18],[4,18],[4,18],[4,18],[2,20],[2,20],[2,20],[6,16],[8,14],[9,12]]};
 const outline=spans[kind]||spans.quarters;
 outline.forEach(([l,r],i)=>{for(let x=l;x<=r;x++)g[i+2][x]='.';});
 const block=(type,x,y,w,h)=>{for(let j=y;j<y+h;j++)for(let i=x;i<x+w;i++)g[j][i]='#';blocks.push({type,x,y,w,h});};
 const v=n%2;
 if(kind==='quarters'){block('bed',4,5,2,3);block('bed',16,5,2,3);block('table',v?6:13,11,3,2);block('cabinet',8,3,2,1);block('hearth',13,3,2,1);}
 if(kind==='loft'){block('bench',3,6,4,2);block('cabinet',14,3,3,1);block('table',12,10,3,2);block('hearth',8,3,2,1);}
 if(kind==='archive'){block('shelf',5,3,3,1);block('shelf',13,3,3,1);block('shelf',5,7,1,4);block('shelf',16,7,1,4);block('table',8,11,5,2);}
 if(kind==='chapel'){block('altar',9,3,2,1);for(const y of [7,10]){block('pew',v?5:4,y,3,1);block('pew',14,y,3,1);}}
 if(kind==='cistern'){block('pool',7,7,8,4);block('bench',4,5,2,1);block('cabinet',16,12,2,1);}
 if(kind==='garden'){block('planter',4,6,3,2);block('planter',15,6,3,2);block('planter',5,11,2,2);block('bench',14,12,3,1);}
 return{width,height,floor:g.map(r=>r.join('')),blocks,architecture:{version:1,style:kind,variant:v,outline:outline.map(([l,r],i)=>({y:i+2,left:l,right:r})),entry:[10,17],scale:'48px per floor unit; furniture footprints use the same units'}};
}
export function expandExploration(data,content){if(!content||data.explorationVersion)return data;data.explorationVersion=1;for(const m of data.campaign.missions){const c=content[m.id-1],anchor=data.scenes.find(r=>r.chapter===m.id&&r.key===c.anchor)||data.scenes.find(r=>r.chapter===m.id),id='district:'+m.id,used=[{xy:anchor.arrive}],entry=place(anchor,anchor.arrive,used);if(!entry)throw Error('No exploration doorway in '+anchor.key);used.push({xy:entry});const outside=place(anchor,entry,used);const plan=interiorFloor(c.layout,m.id),key='secret_'+m.id,door={type:'portal',xy:entry,to:key,arrive:[10,16],travel_label:c.name,explorationDoor:true};anchor.objects.push(door);const mirror=m.rooms.find(r=>r.location===anchor.location);if(mirror!==anchor)mirror.objects.push({...door});
 const answer=(m.id*7+Math.floor(m.id/4))%3,options=[c.wrong1,c.wrong2];options.splice(answer,0,c.answer);
 const room={...plan,key,location:700+m.id,chapter:m.id,theme:anchor.theme,song:anchor.song||m.field_song,arrive:[10,16],interior:c.layout,title:c.name,doors:[{xy:[10,17],to:anchor.key,arrive:[entry[0],entry[1]]}],objects:[{type:'clue',exploreId:id+':clue',xy:[3,14],label:'Keeper’s note',text:c.clue+'\nA later hand has added: Leave the bundle outside for anyone still on the road.'},{type:'riddle',exploreId:id+':latch',xy:[18,4],label:c.landmark,prompt:'The '+c.landmark+' is connected to a closed compartment. What will you try?',options,answer,success:'A quiet click comes from the back wall. A compartment opens beside the '+c.landmark+'.',failure:'The mechanism stays still. Nothing is spent. Look around for evidence before trying another adjustment.',memory:c.memory,guidanceHints:['Someone who used this room left an account of the mechanism.','Read the keeper’s note, then compare it with the '+c.landmark+'.','The keeper’s practical instruction is: '+c.answer+'.']},{type:'secret',exploreId:id+':keepsake',xy:[18,3],label:'Concealed compartment',hidden:true,lock:id+':latch',locked:'A hidden latch holds this compartment. The '+c.landmark+' may release it.',relic:c.relic,memory:c.memory,reward:{gold:30+m.id*12,ether:1,revive:m.id%4===0?1:0},text:'Behind the panel lies '+c.relic.toLowerCase()+', carefully wrapped against the damp.'},{type:'secret',exploreId:id+':pantry',xy:[3,3],label:'Loose floorboard',hidden:true,reward:{tonic:2,ether:m.id>8?1:0},text:'A board shifts under your hand. A dry bundle is tucked beneath it; the knot has been tied so it can be opened without a knife.'},{type:'listen',xy:[11,4],instrumentStation:true,title:'Clay & Water instrument'}]};
 const authored=investigationProps(m.id);if(authored){Object.assign(room.objects[0],authored.evidence);Object.assign(room.objects[1],authored.control);const xy=place(room,room.arrive,[]);if(!xy)throw Error('No reachable investigation site in '+key);room.objects.push({type:'switch',exploreId:id+':work',xy,...authored.work});room.explorationInvestigation=investigationProfile(m.id).kind;}
 data.scenes.push(room);m.rooms.push(room);
 if(outside){const stash={type:'secret',exploreId:id+':outside',xy:outside,label:'Tucked-away bundle',hidden:true,reward:{gold:15+m.id*5,tonic:1},text:'Behind the old wall trim, a cloth bundle is still dry.'};anchor.objects.push(stash);if(mirror!==anchor)mirror.objects.push({...stash});}
 }
 return data;}
